    #[test]
    fn commit_subjects_are_always_part_of_the_history() {
        let tickets = vec![
            with_state(
                available(
                    "GRLD-1",
                    "2020-01-01T00:00:00+00:00",
                    "2020-01-01T00:00:00+00:00",
                ),
                TicketState::Unavailable,
            ),
            available(
                "GRLD-2",
                "2021-01-01T00:00:00+00:00",
                "2021-01-01T00:00:00+00:00",
            ),
        ];
        let commits = vec![
            commit("2024-01-01T00:00:00+00:00", "GRLD-1 first"),
            commit("2024-03-01T00:00:00+00:00", "Fix  NPE"),
            commit("2024-02-01T00:00:00+00:00", "Fix NPE"),
            commit("2024-04-01T00:00:00+00:00", "Bump version"),
            commit("2024-05-01T00:00:00+00:00", " "),
            commit(
                "2024-06-01T00:00:00+00:00",
                "Merge branch 'feature/GRLD-1' into master",
            ),
            commit("2024-07-01T00:00:00+00:00", "Merge pull request #12 from x"),
            commit("2023-01-01T00:00:00+00:00", "Initial"),
        ];
        let subjects = vec![
            "Bump version".to_string(),
            "Fix NPE".to_string(),
            "GRLD-1 first".to_string(),
        ];
        let history = select_history(&tickets, &commits, &config(3)).unwrap();
        assert_eq!(keys(&history), ["GRLD-2"]);
        assert_eq!(
            history.commits, subjects,
            "newest first, merges and blanks dropped, deduplicated, capped at 3, next to the tickets"
        );
        let prompt = member_prompt(&member(), &history, 0);
        assert!(
            prompt.ends_with(
                "\
Tickets (the work it was created for, then the most recent changes, newest first):
- Created for GRLD-2 (Story): Summary of GRLD-2.
  Reason: Purpose of GRLD-2.
Commits (most recent messages, newest first):
- Bump version
- Fix NPE
- GRLD-1 first
CONTEXT>>>
"
            ),
            "{prompt}"
        );
        let commits_only = select_history(&tickets[..1], &commits, &config(3)).unwrap();
        assert_eq!(
            commits_only,
            History {
                tickets: Vec::new(),
                commits: subjects.clone(),
            }
        );
        let prompt = member_prompt(&member(), &commits_only, 0);
        assert!(
            prompt.contains(
                "Tickets: (none)\nCommits (most recent messages, newest first):\n- Bump version\n"
            ),
            "{prompt}"
        );
        assert_eq!(
            select_history(&[], &commits, &config(3)).unwrap(),
            commits_only
        );
        assert_eq!(
            select_history(&[], &[], &config(3)).unwrap(),
            History::default()
        );
        let none = DescribeConfig {
            commit_subjects: 0,
            ..config(3)
        };
        assert!(
            select_history(&tickets, &commits, &none)
                .unwrap()
                .commits
                .is_empty()
        );
    }

    #[test]
    fn only_chosen_tickets_can_make_a_member_incomplete() {
        let old = available(
            "GRLD-1",
            "2020-01-01T00:00:00+00:00",
            "2020-01-01T00:00:00+00:00",
        );
        let unsummarised = with_state(
            available(
                "GRLD-2",
                "2021-01-01T00:00:00+00:00",
                "2021-01-01T00:00:00+00:00",
            ),
            TicketState::Available {
                issue_type: "Bug".to_string(),
                summary: Summary::Missing,
            },
        );
        assert_eq!(
            select_history(&[old.clone(), unsummarised.clone()], &[], &config(3)),
            Err(incomplete(&[], &["GRLD-2"]))
        );
        assert_eq!(
            keys(&select_history(&[old.clone(), unsummarised.clone()], &[], &config(0)).unwrap()),
            ["GRLD-1"],
            "a ticket that is not chosen does not need a summary"
        );

        let newer = available(
            "GRLD-5",
            "2024-01-01T00:00:00+00:00",
            "2024-01-01T00:00:00+00:00",
        );
        let unknown = with_state(
            available(
                "GRLD-3",
                "2022-01-01T00:00:00+00:00",
                "2022-01-01T00:00:00+00:00",
            ),
            TicketState::Unknown,
        );
        let history = select_history(
            &[old.clone(), newer.clone(), unknown.clone()],
            &[],
            &config(1),
        )
        .unwrap();
        assert_eq!(
            keys(&history),
            ["GRLD-1", "GRLD-5"],
            "an unfetched ticket that would not be chosen does not block"
        );
        let resolved = with_state(unknown.clone(), TicketState::Unavailable);
        assert_eq!(
            select_history(&[old.clone(), newer.clone(), resolved], &[], &config(1)).unwrap(),
            history,
            "whichever way it resolves, the choice stays the same"
        );
        assert_eq!(
            select_history(&[old.clone(), newer, unknown.clone()], &[], &config(3)),
            Err(incomplete(&["GRLD-3"], &[])),
            "chosen once the cap allows it"
        );
        assert_eq!(
            select_history(
                &[unknown.clone(), unsummarised],
                &[commit("2024-01-01T00:00:00Z", "x")],
                &config(3)
            ),
            Err(incomplete(&["GRLD-3"], &["GRLD-2"])),
            "an unfetched ticket competes with available ones, commits do not stand in"
        );
        let err = select_history(&[unknown], &[], &config(3)).unwrap_err();
        assert_eq!(err.to_string(), "not fetched: GRLD-3");
        assert_eq!(err.keys().collect::<Vec<_>>(), ["GRLD-3"]);
    }

